// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.List;

import org.junit.jupiter.api.Test;

class FrontierSignedAgmsDeltaAccumulatorTest {

	@Test
	void compactCoordinatesRetainSubjectObjectContextAndRejectPredicate() {
		int lanes = 2;
		int width = 16;
		int componentStride = lanes * width;

		assertEquals(0, FrontierSignedAgmsDeltaAccumulator.coordinate(0, 0, 0, 0, lanes, width));
		assertEquals(componentStride,
				FrontierSignedAgmsDeltaAccumulator.coordinate(0, 2, 0, 0, lanes, width));
		assertEquals(2 * componentStride,
				FrontierSignedAgmsDeltaAccumulator.coordinate(0, 3, 0, 0, lanes, width));
		assertEquals(3 * componentStride,
				FrontierSignedAgmsDeltaAccumulator.coordinate(1, 0, 0, 0, lanes, width));
		assertThrows(IllegalArgumentException.class,
				() -> FrontierSignedAgmsDeltaAccumulator.coordinate(0, 1, 0, 0, lanes, width));
	}

	@Test
	void sparseRowsGroupByPredicateAcrossExplicitAndInferredCompactedPlanes() {
		int lanes = 2;
		int width = 16;
		List<FrontierMutation> mutations = List.of(
				new FrontierMutation(1L, 1L, true, true, 11L, 7L, 101L, 0L),
				new FrontierMutation(2L, 2L, false, false, 12L, 7L, 102L, 19L));
		FrontierSignedAgmsDeltaAccumulator accumulator = new FrontierSignedAgmsDeltaAccumulator(
				mutations, lanes, width);
		mutations.forEach(accumulator::add);

		FrontierSignedAgmsDeltaAccumulator.SparseRows rows = accumulator.sparseRows();
		assertEquals(12, rows.coordinates().length,
				"two mutations times three consumed components times two lanes");
		assertTrue(Arrays.stream(rows.predicates()).allMatch(predicate -> predicate == 7L));
		int planeStride = 3 * lanes * width;
		assertTrue(Arrays.stream(rows.coordinates()).anyMatch(coordinate -> coordinate < planeStride));
		assertTrue(Arrays.stream(rows.coordinates()).anyMatch(coordinate -> coordinate >= planeStride));
		assertTrue(Arrays.stream(rows.coordinates()).allMatch(coordinate -> coordinate < 2 * planeStride));

		long expectedHeap = 1024L * 1024L
				+ (long) mutations.size() * 3L * lanes * 64L
				+ (long) mutations.size() * 32L;
		assertEquals(expectedHeap,
				FrontierSignedAgmsDeltaAccumulator.maximumHeapBytes(mutations.size(), lanes));
	}
}
